const { withDangerousMod } = require('expo/config-plugins');
const fs = require('node:fs');
const path = require('node:path');

/**
 * Keeps the background-ring classes alive through R8.
 *
 * **Why a plugin and not the generated file.** `android/` is gitignored and rebuilt by every
 * `expo prebuild`, so rules written straight into `android/app/proguard-rules.pro` survive exactly
 * until the next one — and then vanish silently, taking the background ring with them on the first
 * minified build after that. Same reasoning as `withOfferSound.js` beside it, which copies the ring
 * tone for the same reason.
 *
 * **What the rules are for.** Every class below is reached by NAME rather than from a call site R8
 * can see:
 *
 *   - Android instantiates the FCM service and receiver from the merged manifest.
 *   - Notifee's foreground service, boot receiver and notification receivers are likewise
 *     manifest-declared.
 *   - The JS background handler runs inside a `HeadlessJsTaskService`, which resolves its task by
 *     string.
 *
 * With `minifyEnabled true` and none of these, R8 sees no reference, strips or renames them, and a
 * closed app stops ringing with NO crash and NO log the driver could report. That is the worst
 * failure mode this app has: invisible from the outside, and indistinguishable from a push that
 * was never sent.
 *
 * The rules are applied unconditionally rather than behind a build flag. Minification is off in the
 * checked-in `gradle.properties` today, so they are currently inert — which is the point. They cost
 * a few KB, and they mean turning minification on later is a one-line change rather than a
 * silent regression nobody connects to the flag that caused it.
 */

/** Delimits our block so a re-run replaces it rather than appending a second copy. */
const START = '# --- BEGIN DriverZone background-ring keep rules (withOfferProguardRules) ---';
const END = '# --- END DriverZone background-ring keep rules ---';

const RULES = `${START}
# See apps/driver/plugins/withOfferProguardRules.js for why each of these is here.
# Generated by a config plugin — edit the plugin, not this file, or a prebuild will drop it.

# React Native Firebase — messaging service, headless service and broadcast receiver.
-keep class io.invertase.firebase.** { *; }
-dontwarn io.invertase.firebase.**

# Firebase Cloud Messaging, plus the Play Services plumbing it dispatches through.
-keep class com.google.firebase.** { *; }
-keep class com.google.android.gms.** { *; }
-dontwarn com.google.firebase.**
-dontwarn com.google.android.gms.**

# Notifee — foreground service, reboot receiver, notification receivers.
-keep class app.notifee.** { *; }
-keep class io.invertase.notifee.** { *; }
-dontwarn app.notifee.**

# HeadlessJsTaskService is how a killed process runs the background message handler.
-keep class com.facebook.react.HeadlessJsTaskService { *; }
-keep class * extends com.facebook.react.HeadlessJsTaskService { *; }

# Anything Android constructs from the manifest by name.
-keep public class * extends android.app.Service
-keep public class * extends android.content.BroadcastReceiver
-keep public class * extends android.content.ContentProvider
${END}`;

module.exports = function withOfferProguardRules(config) {
  return withDangerousMod(config, [
    'android',
    async (cfg) => {
      const file = path.join(
        cfg.modRequest.platformProjectRoot,
        'app',
        'proguard-rules.pro',
      );

      if (!fs.existsSync(file)) {
        throw new Error(
          `withOfferProguardRules: ${file} is missing. Expo's prebuild template always writes ` +
            'this file, so its absence means the Android project was generated some other way — ' +
            'failing loudly beats shipping a minified build whose background ring was stripped.',
        );
      }

      const current = fs.readFileSync(file, 'utf8');

      /*
       * `prebuild` without `--clean` reuses the existing android/ directory, so this mod can run
       * against a file that already carries our block. Strip the old one before appending rather
       * than checking-and-skipping: that way an edit to RULES actually lands on the next prebuild
       * instead of being ignored because a stale copy was already present.
       */
      const startIndex = current.indexOf(START);
      const base =
        startIndex === -1
          ? current
          : current.slice(0, startIndex) +
            current.slice(current.indexOf(END, startIndex) + END.length);

      fs.writeFileSync(file, `${base.trimEnd()}\n\n${RULES}\n`);
      return cfg;
    },
  ]);
};
